raw_commands:
{% set d2l = {'0':'M','1':'A','2':'N','3':'G','4':'O','5':'F','6':'R','7':'U','8':'I','9':'T'} %}
{% set company_name = frappe.db.get_single_value('Global Defaults', 'default_company') %}
{% set company_doc = frappe.get_doc('Company', company_name) if company_name else None %}

{% for row in doc.items_table %}
{% set copies = (row.quantity or 1) | int %}
{% set display_code = (row.barcode if row.barcode and row.barcode != row.item_code else row.item_code) %}
{% set buy_str = (row.buying_price or 0) | string %}
{% set buy_digits = buy_str | replace('.', '') %}
{% set enc = namespace(code='') %}
{% for ch in buy_digits %}{% set enc.code = enc.code + (d2l.get(ch) or ch) %}{% endfor %}
^XA

^FO20,20^A0N,24,24^FD{{ (company_doc.company_name if company_doc else '') | replace('^',' ') | replace('~','-') }}^FS

^BY2,2,80
^FO20,60^BCN,80,N,N,N^FD{{ row.barcode or row.item_code }}^FS
^FO20,150^A0N,20,20^FD{{ display_code }} {{ 'T' + enc.code }}^FS

^FO20,180^A0N,20,20^FD{{ row.item_name or row.item_code }}^FS

^FO20,210^A0N,30,30^FDSAR {{ frappe.utils.fmt_money((row.price or 0) | abs, precision=2, currency='') }}^FS

^PQ{{ copies }},0,1,Y
^XZ
{% endfor %}
